functions.rejection:
def rejection(record, controller, state, truck):
    from core.longitudinal import context
    if (record['context'] != simple_auto_context(state)
            or tuple(record['command_context']) != context(state)):
        return 'continuous service brake activation or route identity changed'
    current = receipt(controller)
    if not current.get('positive') or current.get('chain') != record['chain']:
        return 'continuous service brake write interrupted or backend unavailable'
    now = time.monotonic()  # after identity IPC reads; no source retimestamping
    if not 0. <= now-current.get('returned_at', float('-inf')) <= .5:
        return 'continuous service brake write evidence expired'
    if truck.get('parkBrake') is not False:
        return 'parking brake changed or became unknown during service hold; driver takeover'
    # userBrake/userThrottle do not identify the owner of the input mix. A
    # positive value must not be misclassified as a proven manual intervention.
    # Explicit N/UI cancellation and observed motion/R revoke the state.
    if record.get('phase') == 'holding' and abs(float(truck['speed'])) > .05:
        return 'vehicle motion observed during continuous service brake hold'
    return ''

functions.planned_stop:
def planned_stop(decision):
    if not decision or decision.get('emergency') or decision.get('brake', 0) <= 0:
        return False
    evidence = decision.get('stopping_evidence') or {}
    traffic = evidence.get('traffic') or {}
    acc = evidence.get('acc') or {}
    policy = evidence.get('policy') or {}
    # A prospective red ahead does not turn an unrelated cruise/curve brake
    # into a stop-and-wait commitment. Bind the chain to the winning request.
    return bool((decision.get('source') == 'traffic_light' and traffic.get('light_brake', 0) > 0)
                or (decision.get('source') == 'acc'
                    and acc.get('following_status') in ('candidate', 'source_lost'))
                or (decision.get('source') in ('toll', 'policy', 'speed_policy')
                    and (policy.get('reason') == 'toll stop/payment'
                         or decision.get('reason') == 'toll stop/payment')))

functions._compute_planned_speed:
def _compute_planned_speed(self, dt, truck=None):
        """Lowest safe speed (m/s) implied by all the limits right now."""
        if truck is None:
            truck = self.sdk.telemetry.get("truck", {}) or {}
        limits = []
        spatial_limits = []
        # A preference above the requested cruise speed is not a dependency
        # of the decision. Keep dynamic traffic evidence leased independently.
        requested = self.sdk.get("acc_target_speed")
        try:
            limits.append(number(requested, 0., 160.) / 3.6)
        except (TypeError, ValueError, OverflowError):
            pass

        # 1. Road-class cap (km/h → m/s), published by the map plugin.
        strict = self.sdk.get("longitudinal_control_schema") == 1
        road, _ = read(self.sdk.shared_state, "road", binding=getattr(self, "_longitudinal_binding", None)) if strict else (None, "")
        road_cap = (road.get("speed_cap_kmh") if road else None) if strict else self.sdk.get("road_speed_cap")
        if road_cap:
            try:
                limits.append(float(road_cap) / 3.6)
                if road:
                    spatial_limits.append((float(road_cap) / 3.6, road))
            except (TypeError, ValueError):
                pass

        # 2. Posted in-game speed limit (m/s already, 0 = unknown).
        sl = truck.get("speedLimit", 0.0) or 0.0
        if 0.5 < sl < 200:
            limits.append(float(sl))

        # 3. Curve-safe speed from the measured path curvature.
        curve = curve_input(self.sdk.shared_state, binding=getattr(self, "_longitudinal_binding", None)) if strict else None
        radius = (curve["radius_m"] if curve else None) if strict else self.sdk.get("path_curvature_radius")
        if radius:
            try:
                R = float(radius)
                distance = (curve["distance_m"] if strict else float(self.sdk.get(
                    "path_curve_distance_m", 0.0) or 0.0))
                curve_limit = (curve_constraint_speed(curve, float(truck['speed'])) if curve
                    else curve_speed_envelope(R, distance, float(truck['speed']))[0])
                if math.isfinite(curve_limit):
                    limits.append(curve_limit)
                    if curve:
                        spatial_limits.append((curve_limit, curve))
            except (TypeError, ValueError, OverflowError):
                pass

        # 4. Lead vehicle: hold a ~3 s time-gap.
        traffic, _ = read(self.sdk.shared_state, "traffic", binding=getattr(self, "_longitudinal_binding", None)) if strict else (None, "")
        if traffic:
            from core.longitudinal import signal_approach_speed_limit
            approach_cap=signal_approach_speed_limit(traffic,float(truck['speed']))
            if approach_cap is not None:limits.append(approach_cap)
        lead = (traffic.get("lead_distance") if traffic else None) if strict else self.sdk.get("lead_distance")
        # Route-aligned following is owned by ACC's existing speed controller;
        # do not add a second distance/3 cap on top of its time-gap law.
        following = traffic.get('following') if traffic else None
        if lead and lead > 0 and not (self.sdk.get('longitudinal_acc_active')
                and isinstance(following, dict) and following.get('status')
                    in ('candidate', 'no_candidate_unproven_coverage')):
            try:
                limits.append(float(lead) / 3.0)
            except (TypeError, ValueError):
                pass

        # 5. Red/yellow light ahead: ramp to a near-stop as we approach.
        light = (traffic.get("light") if traffic else None) if strict else self.sdk.get("traffic_light")
        if light:
            color = light.get("color")
            from core.longitudinal import signal_stop_speed_limit
            stop_limit = signal_stop_speed_limit(light, float(truck['speed']))
            if stop_limit is not None:
                limits.append(stop_limit)
            else:
                ldist = float(light.get("distance", 999.0) or 999.0)
                if color in ("red", "yellow") and ldist < 70.0:
                    limits.append(max(0.0, ldist / 4.0))

        plan = min(limits) if limits else 25.0
        plan = max(0.0, min(plan, 40.0))   # clamp 0..144 km/h
        dependencies = ([traffic] if traffic_required(traffic) else [])
        dependencies.extend(value for limit, value in spatial_limits if limit <= plan)
        self._longitudinal_dependencies = dependencies
        self._longitudinal_policy_expiry = min((v["expires_at"] for v in dependencies),
                                               default=float("inf"))

        # Asymmetric lag: drop fast (safe), rise slow (don't lunge into trouble).
        if self._planned is None:
            self._planned = plan
        else:
            rise = min(3.0 * dt, 1.0)
            fall = min(12.0 * dt, 1.0)
            if plan < self._planned:
                self._planned += (plan - self._planned) * fall
            else:
                self._planned += (plan - self._planned) * rise
        # A smoothed preference may rise slowly, but cannot override a
        # currently lower hard constraint. No regulator gain is changed.
        return float(min(self._planned, plan))
